//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_ORBIT_YAW_BEHAVIOUR(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.ORBIT_YAW_BEHAVIOUR
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.ORBIT_YAW_BEHAVIOUR_HOLD_FRONT_TO_CIRCLE_CENTER.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.ORBIT_YAW_BEHAVIOUR
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.ORBIT_YAW_BEHAVIOUR_HOLD_FRONT_TO_CIRCLE_CENTER, dec)
	})
}
